  1117				rel, err := filepath.Rel(repoDir, child)
  1118				if err != nil {
  1119					return nil
  1120				}
  1121				relSlash := filepath.ToSlash(rel)
  1122				if _, err := validateSemanticProviderPath(relSlash); err != nil {
  1123					return nil
  1124				}
  1125				content = appendFileFingerprintContent(content, child, relSlash)
  1126				return nil
  1127			})
  1128			return content
  1129		}
  1130		return appendFileFingerprintContent(content, path, clean)
