  1208	func semanticStaleReport(ctx context.Context, opts Options, target string) (staleReport, error) {
  1209		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
  1210		if err != nil {
  1211			return staleReport{}, err
  1212		}
  1213		if !local {
  1214			return staleReport{}, fmt.Errorf("stale requires a local repository path: %s", target)
  1215		}
  1216		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1217		if err != nil {
  1218			return staleReport{}, err
  1219		}
  1220		manifest, err := loadBrainManifest(storage.BrainDir)
  1221		if err != nil {
  1222			return staleReport{}, err
  1223		}
  1224		axes := map[string]staleAxis{}
  1225		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
  1226			axes["semantic"] = staleAxis{State: "missing", Detail: "no semantic source in manifest"}
  1227			return staleReport{Severity: "unsafe", Axes: axes}, nil
  1228		}
  1229		source := manifest.Sources.Semantic
  1230		if source.SnapshotPath == "" {
  1231			axes["snapshot"] = staleAxis{State: "unsafe", Detail: "semantic snapshot_path is missing"}
  1232		} else if _, err := validateSemanticSnapshotPath(source.SnapshotPath); err != nil {
  1233			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1234		} else if err := rejectSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(source.SnapshotPath)); err != nil {
  1235			axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1236		} else {
  1237			snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(source.SnapshotPath))
  1238			snapshotHeader, snapshotCounts, snapshotErr := readSemanticSnapshotSummary(snapshotPath, storage.Key)
  1239			if snapshotErr != nil {
  1240				axes["snapshot"] = staleAxis{State: "unsafe", Detail: snapshotErr.Error()}
  1241			} else if err := validateSemanticSourceMatchesSnapshot(source, snapshotHeader, snapshotCounts); err != nil {
  1242				axes["snapshot"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1243			} else {
  1244				axes["snapshot"] = staleAxis{State: "ok", Detail: source.SnapshotPath}
  1245			}
  1246		}
  1247		head, _ := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD")
  1248		branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
  1249		dirty, dirtyErr := worktreeDirty(ctx, opts.Runner, repoDir)
  1250		if source.Commit == head {
  1251			axes["head"] = staleAxis{State: "ok", Current: head, Indexed: source.Commit}
  1252		} else {
  1253			axes["head"] = staleAxis{State: "stale", Current: head, Indexed: source.Commit}
  1254		}
  1255		if source.Branch == "" || source.Branch == branch {
  1256			axes["branch_tip"] = staleAxis{State: "ok", Current: branch, Indexed: source.Branch}
  1257		} else {
  1258			axes["branch_tip"] = staleAxis{State: "stale", Current: branch, Indexed: source.Branch}
  1259		}
  1260		switch {
  1261		case dirtyErr != nil:
  1262			axes["worktree"] = staleAxis{State: "unsafe", Detail: "worktree status unavailable: " + dirtyErr.Error()}
  1263		case dirty && source.WorktreeMode != "worktree":
  1264			axes["worktree"] = staleAxis{State: "dirty-unindexed", Detail: "semantic index is based on committed HEAD"}
  1265		case dirty && source.WorktreeHash != "" && source.WorktreeHash != worktreeFingerprint(ctx, opts.Runner, repoDir):
  1266			axes["worktree"] = staleAxis{State: "dirty-stale", Detail: "dirty worktree changed since semantic indexing"}
  1267		case dirty:
  1268			axes["worktree"] = staleAxis{State: "dirty-indexed"}
  1269		case source.WorktreeMode == "worktree":
  1270			axes["worktree"] = staleAxis{State: "worktree-overlay-stale", Detail: "active semantic index was built from dirty content but worktree is now clean"}
  1271		default:
  1272			axes["worktree"] = staleAxis{State: "clean"}
  1273		}
  1274		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
  1275			axes["provider"] = staleAxis{State: "degraded", Detail: "semantic provider was skipped"}
  1276		} else if err := validateSemanticSchema(source.SchemaVersion); err != nil {
  1277			axes["provider"] = staleAxis{State: "unsafe", Detail: err.Error()}
  1278		} else if !source.NoEgressVerified {
  1279			axes["provider"] = staleAxis{State: "degraded", Detail: "provider no-egress status was not verified"}
  1280		} else {
  1281			axes["provider"] = staleAxis{State: "ok", Detail: source.Provider + " " + source.ProviderVersion}
  1282		}
  1283		if source.Provider == "skipped" || semanticWarningsContainCode(source.Warnings, "provider_skipped") {
  1284			axes["semantic_completeness"] = staleAxis{State: "unsafe", Detail: "semantic facts unavailable"}
  1285		} else if len(source.PartialFailures) > 0 {
  1286			axes["semantic_completeness"] = staleAxis{State: "degraded", Detail: strconv.Itoa(len(source.PartialFailures)) + " partial failures"}
