  1752			return nil, err
  1753		}
  1754		generationRoot := filepath.Join(brainDir, generationPath)
  1755		info, err := os.Lstat(generationRoot)
  1756		if err != nil {
  1757			return nil, fmt.Errorf("semantic generation missing: %w", err)
