  1764		}
  1765		var paths []string
  1766		err = filepath.WalkDir(generationRoot, func(path string, d os.DirEntry, walkErr error) error {
  1767			if walkErr != nil {
  1768				return walkErr
  1769			}
  1770			rel, err := filepath.Rel(brainDir, path)
  1771			if err != nil {
  1772				return err
  1773			}
  1774			if err := rejectSymlinkPathComponents(brainDir, rel); err != nil {
  1775				return err
  1776			}
  1777			if d.IsDir() {
  1778				return nil
  1779			}
  1780			paths = append(paths, rel)
  1781			return nil
  1782		})
  1783		if err != nil {
  1784			return nil, err
  1785		}
  1786		sort.Strings(paths)
