  1868	func rejectSymlinkPathComponents(root, rel string) error {
  1869		clean := filepath.Clean(rel)
  1870		if filepath.IsAbs(clean) || clean == "." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
  1871			return fmt.Errorf("path is outside root: %s", rel)
  1872		}
  1873		current := root
  1874		for _, part := range strings.Split(clean, string(filepath.Separator)) {
  1875			current = filepath.Join(current, part)
  1876			info, err := os.Lstat(current)
  1877			if err != nil {
  1878				return err
  1879			}
  1880			if info.Mode()&os.ModeSymlink != 0 {
  1881				return fmt.Errorf("path component must not be a symlink: %s", rel)
  1882			}
  1883		}
  1884		rootResolved, err := filepath.EvalSymlinks(root)
  1885		if err != nil {
  1886			return err
  1887		}
  1888		pathResolved, err := filepath.EvalSymlinks(filepath.Join(root, clean))
  1889		if err != nil {
  1890			return err
  1891		}
  1892		if !pathInside(rootResolved, pathResolved) {
  1893			return fmt.Errorf("path escapes root through symlinks: %s", rel)
  1894		}
  1895		return nil
  1896	}
  1897	
