  1920	func rejectBundleOutputInsideBrain(output, brainDir string) error {
  1921		outputAbs, err := filepath.Abs(output)
  1922		if err != nil {
  1923			return err
  1924		}
  1925		brainAbs, err := filepath.Abs(brainDir)
  1926		if err != nil {
  1927			return err
  1928		}
  1929		if pathInside(brainAbs, outputAbs) {
  1930			return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
  1931		}
  1932		outputResolved, err := resolvedOutputPath(output)
  1933		if err != nil {
  1934			return err
  1935		}
  1936		brainResolved, err := filepath.EvalSymlinks(brainDir)
  1937		if err != nil {
  1938			brainResolved = brainAbs
  1939		}
  1940		if pathInside(brainResolved, outputResolved) {
  1941			return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
  1942		}
  1943		return nil
  1944	}
