  1946	func rejectBundleOutputHardLink(output, brainDir string) error {
  1947		outputInfo, err := os.Stat(output)
  1948		if err != nil {
  1949			if os.IsNotExist(err) {
  1950				return nil
  1951			}
  1952			return err
  1953		}
  1954		if outputInfo.IsDir() {
  1955			return fmt.Errorf("bundle output path is a directory: %s", output)
  1956		}
  1957		return filepath.WalkDir(brainDir, func(path string, d os.DirEntry, walkErr error) error {
  1958			if walkErr != nil {
  1959				return walkErr
  1960			}
  1961			if d.IsDir() {
  1962				return nil
  1963			}
  1964			info, err := os.Stat(path)
  1965			if err != nil {
  1966				return err
  1967			}
  1968			if os.SameFile(outputInfo, info) {
  1969				return fmt.Errorf("bundle output must not be a hard link to brain file: %s", path)
  1970			}
  1971			return nil
  1972		})
  1973	}
