  1975	func pathInside(root, path string) bool {
  1976		rel, err := filepath.Rel(root, path)
  1977		if err != nil {
  1978			return false
  1979		}
  1980		return rel == "." || (!strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != "..")
  1981	}
  1982	
  1983	func resolvedOutputPath(output string) (string, error) {
  1984		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  1985			return filepath.Abs(resolved)
  1986		}
  1987		absOutput, err := filepath.Abs(output)
  1988		if err != nil {
  1989			return "", err
  1990		}
  1991		volume := filepath.VolumeName(absOutput)
  1992		rest := strings.TrimPrefix(absOutput, volume)
  1993		parts := strings.Split(strings.Trim(rest, string(filepath.Separator)), string(filepath.Separator))
  1994		existing := volume + string(filepath.Separator)
  1995		var missing []string
  1996		for i, part := range parts {
  1997			candidate := filepath.Join(existing, part)
  1998			if _, err := os.Lstat(candidate); err != nil {
  1999				if os.IsNotExist(err) {
  2000					missing = parts[i:]
  2001					break
  2002				}
  2003				return "", err
  2004			}
  2005			existing = candidate
  2006		}
  2007		resolvedExisting, err := filepath.EvalSymlinks(existing)
  2008		if err != nil {
  2009			return "", err
  2010		}
  2011		for _, part := range missing {
  2012			resolvedExisting = filepath.Join(resolvedExisting, part)
  2013		}
  2014		return filepath.Abs(resolvedExisting)
  2015	}
