  2017	func runSemanticBundleImport(ctx context.Context, cmd *cobra.Command, opts Options, archive, expectedChecksum string) error {
  2018		if err := rejectRemoteBundlePath(archive); err != nil {
  2019			return err
  2020		}
  2021		expectedChecksum = strings.ToLower(strings.TrimSpace(expectedChecksum))
  2022		if len(expectedChecksum) != sha256.Size*2 {
  2023			return errors.New("expected bundle checksum must be a hex SHA-256 digest")
  2024		}
  2025		f, err := os.Open(archive)
  2026		if err != nil {
  2027			return err
  2028		}
  2029		defer f.Close()
  2030		sum, err := readerSHA256(f)
  2031		if err != nil {
  2032			return err
  2033		}
  2034		if sum != expectedChecksum {
  2035			return fmt.Errorf("bundle checksum mismatch: got %s, want %s", sum, expectedChecksum)
  2036		}
  2037		repoDir, err := exportRepoDir(opts.Env)
  2038		if err != nil {
  2039			return err
  2040		}
  2041		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  2042		if err != nil {
  2043			return err
  2044		}
  2045		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
  2046		if err != nil {
  2047			return err
  2048		}
  2049		defer unlock()
  2050		if _, err := f.Seek(0, io.SeekStart); err != nil {
  2051			return err
  2052		}
  2053		if err := os.MkdirAll(filepath.Dir(storage.BrainDir), 0o700); err != nil {
  2054			return err
  2055		}
  2056		tmpDir, err := os.MkdirTemp(filepath.Dir(storage.BrainDir), ".bundle-import-*")
  2057		if err != nil {
  2058			return err
  2059		}
  2060		defer os.RemoveAll(tmpDir)
  2061		tr := tar.NewReader(f)
  2062		imported := 0
  2063		var totalBytes int64
  2064		for {
  2065			header, err := tr.Next()
  2066			if errors.Is(err, io.EOF) {
  2067				break
  2068			}
  2069			if err != nil {
  2070				return err
  2071			}
  2072			if err := validateBundleEntry(header); err != nil {
  2073				return err
  2074			}
  2075			if header.Size > semanticBundleMaxEntry {
  2076				return fmt.Errorf("bundle entry too large: %s", header.Name)
  2077			}
  2078			imported++
  2079			if imported > semanticBundleMaxFiles {
  2080				return fmt.Errorf("bundle has too many entries: %d", imported)
  2081			}
  2082			totalBytes += header.Size
  2083			if totalBytes > semanticBundleMaxTotal {
  2084				return fmt.Errorf("bundle total size exceeds limit: %d", totalBytes)
  2085			}
  2086			target := filepath.Join(tmpDir, filepath.FromSlash(header.Name))
  2087			if err := os.MkdirAll(filepath.Dir(target), 0o700); err != nil {
