   175		data, err := json.MarshalIndent(manifest, "", "  ")
   176		if err != nil {
   177			return fmt.Errorf("encode %s: %w", exportManifestFileName, err)
   178		}
   179		data = append(data, '\n')
   180		if err := writeFileAtomic(filepath.Join(outputDir, exportManifestFileName), data, 0o600); err != nil {
   181			return fmt.Errorf("write %s: %w", exportManifestFileName, err)
   182		}
   183		if err := writeFileAtomic(filepath.Join(outputDir, exportReadmeFileName), []byte(renderBrainReadme(manifest)), 0o600); err != nil {
   184			return fmt.Errorf("write brain readme: %w", err)
   185		}
   186		return nil
   187	}
   188	
   189	func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
   190		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
   191			return err
   192		}
   193		tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
   194		if err != nil {
   195			return err
   196		}
   197		tmpName := tmp.Name()
   198		cleanup := true
   199		defer func() {
   200			if cleanup {
   201				_ = os.Remove(tmpName)
   202			}
   203		}()
   204		if _, err := tmp.Write(data); err != nil {
   205			_ = tmp.Close()
   206			return err
   207		}
   208		if err := tmp.Chmod(perm); err != nil {
   209			_ = tmp.Close()
   210			return err
   211		}
   212		if err := tmp.Close(); err != nil {
   213			return err
   214		}
   215		if err := os.Rename(tmpName, path); err != nil {
   216			return err
   217		}
   218		cleanup = false
   219		return nil
   220	}
   221	
   222	func renderBrainReadme(manifest exportManifest) string {
   223		if manifest.Sources == nil || (manifest.Sources.Seed == nil && manifest.Sources.Semantic == nil) {
   224			return renderExportReadme(manifest)
   225		}
   226		return renderCombinedBrainReadme(manifest)
   227	}
